namespace RobinEpple.Common.SourceGenerators.Abstractions;

/// <summary>
/// Explicitly defines how the method generated by the static factory will be called.
/// </summary>
[AttributeUsage(AttributeTargets.Class, AllowMultiple = false, Inherited = false)]
public class StaticFactoryMethodNameAttribute(string name) : Attribute
{
	public string Name { get; } = name;
}
